Subroutine OrdenarDos(a As Integer By Reference, b As Integer By Reference)
  If a > b Then
    Define guardado As Integer <- a;
    a <- b;
    b <- guardado;
  EndIf
EndSubroutine

Algorithm Principal
  Define primero, segundo As Integer;
  Read primero;
  Read segundo;
  OrdenarDos(primero, segundo);
  Write primero, " ", segundo;
EndAlgorithm
